import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const scriptsDirectory = resolve(fileURLToPath(new URL('.', import.meta.url)));
const projectRoot = resolve(scriptsDirectory, '..');
const outputPath = resolve(projectRoot, 'assets/css/ui-v2.bundle.css');
const modalOutputPath = resolve(projectRoot, 'assets/css/ui-modal.bundle.css');
const sources = Object.freeze([
  'assets/css/tokens/ui-v2.css',
  'assets/css/primitives/controls.css',
  'assets/css/components/surface.css',
  'assets/css/components/content.css',
  'assets/css/components/command-row.css',
  'assets/css/components/workflows.css',
  'assets/css/layout/surfaces.css',
  'assets/css/features/layer-panel.css',
  'assets/css/components/editor-shell.css',
  'assets/css/components/panels.css',
  'assets/css/components/mobile-sheets.css',
  'assets/css/components/feedback.css',
  'assets/css/utilities/accessibility.css',
]);
const modalSources = Object.freeze(['assets/css/components/modals.css']);
const sourceContents = sources.map(relativePath => ({
  relativePath,
  content: readFileSync(resolve(projectRoot, relativePath), 'utf8').trim(),
}));

const output = [
  '/* Generated by scripts/build-ui-bundle.mjs. Do not edit manually. */',
  `/* source-count: ${sources.length} */`,
  ...sourceContents.flatMap(({ relativePath, content }) => [
    `/* source: ${relativePath} */`,
    content,
  ]),
  '',
].join('\n\n');

writeFileSync(outputPath, output, 'utf8');
const modalOutput = [
  '/* Generated by scripts/build-ui-bundle.mjs. Do not edit manually. */',
  `/* modal-source-count: ${modalSources.length} */`,
  ...modalSources.flatMap(relativePath => [
    `/* modal-source: ${relativePath} */`,
    readFileSync(resolve(projectRoot, relativePath), 'utf8').trim(),
  ]),
  '',
].join('\n\n');
writeFileSync(modalOutputPath, modalOutput, 'utf8');
console.log(`Generated UI bundle from ${sources.length} stylesheets and modal bundle from ${modalSources.length} stylesheet.`);
